// Nivesh Learn — course catalog + demo portfolio fields.
// Content: the Nivesh Learn curriculum (8 courses / 68 lessons). Data-driven:
// to add a course, append one object to COURSES. `core` holds trusted inline
// <b>/<i> markup rendered via dangerouslySetInnerHTML; `hook` uses {placeholder}
// tokens filled from DEMO (sample data until wired to the portfolio engine).

export interface LearnQuiz { q: string; opts: string[]; a: number; exp: string; }
export interface LearnLesson { _c?: number; id: string; t: string; min: number; core: string; hook: string; q: LearnQuiz; }
export interface LearnModule { title: string; lessons: LearnLesson[]; }
export interface LearnCourse { n: number; title: string; level: string; min: number; prereq: string; promise: string; modules: LearnModule[]; }

